mapper.select:
/* StoreTimeSaleBensonMapper.getStoreTimeSaleBensonList */
SELECT
       tsdt.SALE_HOUR,
       SUM(tsdt.REAL_SALE_AMT) AS REAL_SALE_AMT,
       SUM(tsdt.REAL_SALE_CNT) AS BILL_CNT,
       SUM(tsdt.GUEST_CNT_1)   AS GUEST_CNT
  FROM TB_SL_DAILY_TIME tsdt
 WHERE tsdt.HQ_OFFICE_CD = #{hqOfficeCd}
   AND tsdt.STORE_CD     = #{storeCd}
   AND tsdt.SALE_DATE BETWEEN #{startDate} AND #{endDate}
   AND tsdt.SALE_HOUR BETWEEN #{startTime} AND #{endTime}
 GROUP BY tsdt.SALE_HOUR
 ORDER BY tsdt.SALE_HOUR
